193	                animal.act(newAnimals);
194	                
195	                if (! animal.isAlive())
196	                {
197	                    it.remove();
198	                }
199	            }
200	        }
201	        
202	        // Let all plants act.
203	        for(Iterator<LivingOrganism> it = plants.iterator(); it.hasNext(); ) {
