268	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) 
269	                {
270	                     animal = (Zebra) new Zebra(true, field, location, false, false);
271	                }
272	                else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY)
273	                {
274	                     animal = (Giraffe) new Giraffe(true, field, location, false, false);
275	                }
276	                else if(rand.nextDouble() <= LEMUR_CREATION_PROBABILITY) 
277	                {
278	                     animal = (Lemur) new Lemur(true, field, location, false, false);
279	                }
280	                
281	                if(animal != null) 
282	                {
283	                    animals.add(animal);
284	                }
285	            }
