     import java.util.ArrayList;
     import java.util.Iterator;
     import java.util.List;
     public class Field {
         private static final SimRandom rand = Randomizer.getRandom();
         private final Grid grid;
         // ... delegate methods clear, place, getObjectAt to grid ...
         public Iterator<Location> adjacentLocations(Location location) {
             int[] rows = new int[8]; int[] cols = new int[8]; int count = 0;
             int row = location.getRow(); int col = location.getCol();
             for (int roffset = -1; roffset <= 1; roffset++) {
                 int nextRow = row + roffset;
                 if (nextRow >= 0 && nextRow < grid.getDepth()) {
                     for (int coffset = -1; coffset <= 1; coffset++) {
                         int nextCol = col + coffset;
                         if (nextCol >= 0 && nextCol < grid.getWidth() && (roffset != 0 || coffset != 0)) {
                             rows[count] = nextRow; cols[count] = nextCol; count++;
                         }
                     }
                 }
             }
             // Fisher-Yates — same RNG sequence as Collections.shuffle
             for (int i = count - 1; i > 0; i--) {
                 int j = rand.nextInt(i + 1);
                 int tmpRow = rows[i]; rows[i] = rows[j]; rows[j] = tmpRow;
                 int tmpCol = cols[i]; cols[i] = cols[j]; cols[j] = tmpCol;
             }
             return new AdjacentIterator(rows, cols, count);
         }
         public List<Location> getFreeAdjacentLocations(Location location, Class objectType) {
             List<Location> free = new ArrayList<>(8);
             Iterator<Location> it = adjacentLocations(location);
             while (it.hasNext()) { Location next = it.next(); if (getObjectAt(next, objectType) == null) free.add(next); }
             return free;
         }
         public Location freeAdjacentLocation(Location location, Class objectType) {
             List<Location> free = getFreeAdjacentLocations(location, objectType);
             return free.size() > 0 ? free.get(0) : null;
         }
         public Location randomAdjacentLocation(Location location) { return adjacentLocations(location).next(); }
         private static class AdjacentIterator implements Iterator<Location> {
             private final int[] rows, cols;
             private final int count;
             private int index;
             AdjacentIterator(int[] rows, int[] cols, int count) { this.rows=rows; this.cols=cols; this.count=count; }
             public boolean hasNext() { return index < count; }
             public Location next()   { return new Location(rows[index], cols[index++]); }
         }
     }
     ```

